import java.util.Scanner;

public class Text_Document_Analysis {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int totalChars = scanner.nextInt();
        String inputString = scanner.next();
        StringBuilder mainBuffer = new StringBuilder(inputString);
        StringBuilder underscorePart = new StringBuilder();
        StringBuilder bracketPart = new StringBuilder();
        int position = 0, currentCount = 0, maxCount = 0, maxBracketCount = 0;
        while (position < totalChars) {
            if (mainBuffer.charAt(position) == '(') {
                position++;
                while (mainBuffer.charAt(position) != ')') {
                    bracketPart.append(mainBuffer.charAt(position));
                    position++;
                }
                position++;
                bracketPart.append("_");
                underscorePart.append("_");
            } else {
                underscorePart.append(mainBuffer.charAt(position));
                position++;
            }
        }
        underscorePart.append("_");
        bracketPart.append("_");
        for (int j = 0; j < underscorePart.length(); j++) {
            if (underscorePart.charAt(j) == '_') {
                if (currentCount > maxCount) {
                    maxCount = currentCount;
                }
                currentCount = 0;
            } else {
                currentCount++;
            }
        }
        currentCount = 0;
        for (int j = 0; j < bracketPart.length(); j++) {
            if (bracketPart.charAt(j) == '_') {
                if (currentCount > 0) {
                    maxBracketCount++;
                }
                currentCount = 0;
            } else {
                currentCount++;
            }
        }
        System.out.println(maxCount + " " + maxBracketCount);
    }
}
